1. import type { CartLine } from "./product.ts";
2. import { totalLineWeightGrams } from "./tax.ts";
3. 
4. /**
5.  * ShippingCalculator is the seam consumers (and tests) substitute to compute shipping.
6.  * Implementations must be pure and deterministic for a given input.
7.  */
8. export interface ShippingCalculator {
9.   /**
10.    * @param lines           Cart lines being shipped.
11.    * @param subtotalCents   Subtotal AFTER discounts (used for free-shipping thresholds).
12.    * @returns Shipping cost in cents as a non-negative integer.
13.    */
14.   computeShippingCents(
15.     lines: readonly CartLine[],
16.     subtotalCents: number,
17.   ): number;
18. }
19. 
20. export class FreeShippingCalculator implements ShippingCalculator {
21.   computeShippingCents(
22.     _lines: readonly CartLine[],
23.     _subtotalCents: number,
24.   ): number {
25.     return 0;
26.   }
27. }
28. 
29. /**
30.  * Flat shipping fee with optional free-over-threshold logic.
31.  */
32. export class FlatShippingCalculator implements ShippingCalculator {
33.   constructor(
34.     private readonly flatCents: number,
35.     private readonly freeOverCents?: number,
36.   ) {
37.     if (!Number.isInteger(flatCents) || flatCents < 0) {
38.       throw new RangeError(
39.         `flatCents must be a non-negative integer (got ${flatCents})`,
40.       );
41.     }
42.     if (freeOverCents !== undefined) {
43.       if (!Number.isInteger(freeOverCents) || freeOverCents < 0) {
44.         throw new RangeError(
45.           `freeOverCents must be a non-negative integer (got ${freeOverCents})`,
46.         );
47.       }
48.     }
49.   }
50. 
51.   computeShippingCents(
52.     lines: readonly CartLine[],
53.     subtotalCents: number,
54.   ): number {
55.     if (lines.length === 0) return 0;
56.     if (this.freeOverCents !== undefined && subtotalCents >= this.freeOverCents) {
57.       return 0;
58.     }
59.     return this.flatCents;
60.   }
61. }
62. 
63. export interface WeightBracket {
64.   /** Inclusive upper bound for the bracket, in grams. */
65.   upToGrams: number;
66.   /** Cost in cents for items totalling weight <= upToGrams. */
67.   costCents: number;
68. }
69. 
70. /**
71.  * Weight-bucketed shipping. The bracket whose `upToGrams` first equals-or-exceeds
72.  * the total weight wins. Anything over the heaviest bracket uses an overflow rate
73.  * (defaults to the heaviest bracket cost). Empty carts ship free.
74.  */
75. export class WeightBasedShippingCalculator implements ShippingCalculator {
76.   private readonly sortedBrackets: readonly WeightBracket[];
77. 
78.   constructor(
79.     brackets: readonly WeightBracket[],
80.     private readonly overflowCostCents?: number,
81.   ) {
82.     if (brackets.length === 0) {
83.       throw new Error("at least one weight bracket is required");
84.     }
85.     for (const bracket of brackets) {
86.       if (!Number.isInteger(bracket.upToGrams) || bracket.upToGrams <= 0) {
87.         throw new RangeError("bracket.upToGrams must be a positive integer");
88.       }
89.       if (!Number.isInteger(bracket.costCents) || bracket.costCents < 0) {
90.         throw new RangeError("bracket.costCents must be a non-negative integer");
91.       }
92.     }
93.     if (
94.       overflowCostCents !== undefined &&
95.       (!Number.isInteger(overflowCostCents) || overflowCostCents < 0)
96.     ) {
97.       throw new RangeError("overflowCostCents must be a non-negative integer");
98.     }
99.     this.sortedBrackets = [...brackets].sort((a, b) => a.upToGrams - b.upToGrams);
100.   }
101. 
102.   computeShippingCents(
103.     lines: readonly CartLine[],
104.     _subtotalCents: number,
105.   ): number {
106.     if (lines.length === 0) return 0;
107.     const weight = totalLineWeightGrams(lines);
108.     if (weight === 0) return 0;
109.     for (const bracket of this.sortedBrackets) {
110.       if (weight <= bracket.upToGrams) return bracket.costCents;
111.     }
112.     return (
113.       this.overflowCostCents ??
114.       this.sortedBrackets[this.sortedBrackets.length - 1]!.costCents
115.     );
116.   }
117. }
