import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("adds a product and tracks quantity", () => {
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding same product twice", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("tracks multiple products independently", () => {
    cart.add(productA, 1);
    cart.add(productB, 2);
    expect(cart.itemCount).toBe(3);
  });

  it("rejects non-positive quantity", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const badProduct: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(productA, 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("x", 1)).toThrow("Product x is not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear removes all items", () => {
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copies", () => {
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart.totals() pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("empty cart totals are all zero", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy to subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 2); // subtotal = 2000
    const totals = cart.totals();
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(2000);
    expect(totals.discountCents).toBe(500);
    expect(totals.totalCents).toBe(2000 - 500); // no tax, no shipping
  });

  it("clamps discount to [0, subtotal]: negative discount becomes 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount to [0, subtotal]: over-subtotal discount capped", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("tax is computed on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(productA, 1); // subtotal 1000, discounted = 800
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
  });

  it("shipping receives discounted subtotal and cart lines", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(productA, 1); // subtotal 1000, discounted = 700
    cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700,
    );
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    // discountedSubtotal = 1000 - 200 = 800
    // total = 800 + 80 + 500 = 1380
    expect(totals.totalCents).toBe(1380);
  });

  it("uses custom region for tax", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("clamps negative tax to 0", () => {
